import { apiFetch } from '../lib/api.js'

export interface NoteSummary {
  id: string
  path: string
  type: string
  name: string
  frontmatter: Record<string, unknown>
  updatedAt: string
}

export type VaultTree = Record<string, NoteSummary[]>

export function getVaultTree(vaultId: string): Promise<VaultTree> {
  return apiFetch(`/vaults/${vaultId}/tree`)
}

export interface NoteDetail {
  path: string
  frontmatter: Record<string, unknown>
  body: string
  updatedAt: string
}

export function getNote(vaultId: string, path: string): Promise<NoteDetail> {
  return apiFetch(`/vaults/${vaultId}/notes/${path}`)
}

export interface UpdateNoteInput {
  frontmatter?: Record<string, unknown>
  body?: string
}

export interface UpdateNoteResult {
  id: string
  path: string
  frontmatter: Record<string, unknown>
  body: string
  updatedAt: string
}

export function updateNote(vaultId: string, path: string, input: UpdateNoteInput): Promise<UpdateNoteResult> {
  return apiFetch(`/vaults/${vaultId}/notes/${path}`, { method: 'PUT', body: JSON.stringify(input) })
}

export class ApiError extends Error {
  status: number
  body: unknown

  constructor(status: number, body: unknown) {
    const message =
      typeof body === 'object' && body !== null && 'error' in body && typeof (body as { error: unknown }).error === 'string'
        ? (body as { error: string }).error
        : `Request failed (${status})`
    super(message)
    this.status = status
    this.body = body
  }
}

export async function apiFetch<T>(path: string, init?: RequestInit): Promise<T> {
  const res = await fetch(`/api${path}`, {
    ...init,
    credentials: 'include',
    headers: { 'Content-Type': 'application/json', ...init?.headers },
  })
  const body = await res.json().catch(() => undefined)
  if (!res.ok) throw new ApiError(res.status, body)
  return body as T
}

/** Test-only helper: builds a real Response for stubbed fetch calls. */
export function mockJsonResponse(status: number, body: unknown): Response {
  return new Response(JSON.stringify(body), {
    status,
    headers: { 'Content-Type': 'application/json' },
  })
}

import { afterEach, describe, expect, it, vi } from 'vitest'
import { QueryClient, QueryClientProvider } from '@tanstack/react-query'
import { renderHook, waitFor } from '@testing-library/react'
import { mockJsonResponse } from '../lib/api'
import { useSession } from './useSession'

function wrapper({ children }: { children: React.ReactNode }) {
  const queryClient = new QueryClient({ defaultOptions: { queries: { retry: false } } })
  return <QueryClientProvider client={queryClient}>{children}</QueryClientProvider>
}

describe('useSession', () => {
  afterEach(() => {
    vi.unstubAllGlobals()
  })

  it('resolves the current session on success', async () => {
    vi.stubGlobal(
      'fetch',
      vi.fn().mockResolvedValue(
        mockJsonResponse(200, { id: 'u1', email: 'a@b.com', status: 'active', role: 'member', createdAt: '2026-01-01' }),
      ),
    )

    const { result } = renderHook(() => useSession(), { wrapper })

    await waitFor(() => expect(result.current.isSuccess).toBe(true))
    expect(result.current.data?.email).toBe('a@b.com')
  })

  it('is an error when there is no session', async () => {
    vi.stubGlobal('fetch', vi.fn().mockResolvedValue(mockJsonResponse(401, { error: 'unauthorized' })))

    const { result } = renderHook(() => useSession(), { wrapper })

    await waitFor(() => expect(result.current.isError).toBe(true))
  })
})

import { defineConfig, mergeConfig } from 'vitest/config'
import viteConfig from './vite.config.js'

export default mergeConfig(
  viteConfig,
  defineConfig({
    test: {
      // happy-dom (not jsdom): react-router's data router builds a native
      // Request on every client-side navigation, including <Navigate>
      // redirects. jsdom shadows AbortController/AbortSignal but not
      // Request/fetch, so undici rejects the mismatched signal with
      // "TypeError: RequestInit: Expected signal ... to be an instance of
      // AbortSignal" (vitest-dev/vitest#8374, remix-run/react-router#10158).
      // happy-dom doesn't hit this.
      environment: 'happy-dom',
      setupFiles: ['./src/test/setup.ts'],
      globals: false,
    },
  }),
)
